#!/usr/bin/env python3
"""Parse a Parquet file, extract date/time columns, and output an HTML table."""

import sys
from pathlib import Path

import pandas as pd


def extract_datetime_columns(df: pd.DataFrame) -> pd.DataFrame:
    """Return a DataFrame containing only the date/time columns."""
    dt_cols = df.select_dtypes(include=["datetime64", "datetimetz", "timedelta64"]).columns.tolist()

    # Also try to parse object columns that look like dates
    for col in df.select_dtypes(include=["object"]).columns:
        try:
            parsed = pd.to_datetime(df[col], errors="coerce")
            if parsed.notna().mean() > 0.8:
                df[col] = parsed
                dt_cols.append(col)
        except (ValueError, TypeError):
            pass

    if not dt_cols:
        return pd.DataFrame()
    return df[dt_cols]


def df_to_html(df: pd.DataFrame, title: str = "") -> str:
    """Render a DataFrame as a self-contained HTML page."""
    table_html = df.to_html(index=True, classes="data-table", border=0, na_rep="—")
    return f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>{title}</title>
<style>
  body {{ font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
         margin: 2rem; background: #f8f9fa; color: #212529; }}
  h1 {{ font-size: 1.4rem; }}
  .data-table {{ border-collapse: collapse; width: 100%; background: #fff;
                 box-shadow: 0 1px 3px rgba(0,0,0,.1); }}
  .data-table th, .data-table td {{ padding: 8px 12px; text-align: left;
                                     border-bottom: 1px solid #dee2e6; }}
  .data-table thead th {{ background: #343a40; color: #fff; position: sticky; top: 0; }}
  .data-table tbody tr:hover {{ background: #f1f3f5; }}
  .info {{ color: #6c757d; margin-bottom: 1rem; }}
</style>
</head>
<body>
<h1>{title}</h1>
<p class="info">{len(df)} rows &times; {len(df.columns)} columns</p>
{table_html}
</body>
</html>"""


def main():
    if len(sys.argv) < 2:
        print(f"Usage: {sys.argv[0]} <parquet_file> [output.html]")
        sys.exit(1)

    src = Path(sys.argv[1])
    out = Path(sys.argv[2]) if len(sys.argv) > 2 else src.with_suffix(".html")

    df = pd.read_parquet(src)
    dt_df = extract_datetime_columns(df)

    if dt_df.empty:
        print("No date/time columns found.")
        sys.exit(0)

    html = df_to_html(dt_df, title=f"Date/Time Columns — {src.name}")
    out.write_text(html, encoding="utf-8")
    print(f"Wrote {len(dt_df)} rows, {len(dt_df.columns)} datetime columns → {out}")


if __name__ == "__main__":
    main()
